    }
    if (data.containsKey('master_plan_id')) {
      context.handle(
        _masterPlanIdMeta,
        masterPlanId.isAcceptableOrUnknown(
          data['master_plan_id']!,
          _masterPlanIdMeta,
        ),
      );
    }
    if (data.containsKey('created_at')) {
      context.handle(
        _createdAtMeta,
        createdAt.isAcceptableOrUnknown(data['created_at']!, _createdAtMeta),
      );
    } else if (isInserting) {
      context.missing(_createdAtMeta);
    }
    if (data.containsKey('applied_at')) {
      context.handle(
        _appliedAtMeta,
        appliedAt.isAcceptableOrUnknown(data['applied_at']!, _appliedAtMeta),
      );
    }
    if (data.containsKey('reverted_at')) {
      context.handle(
        _revertedAtMeta,
        revertedAt.isAcceptableOrUnknown(data['reverted_at']!, _revertedAtMeta),
      );
    }
    if (data.containsKey('user_feedback')) {
      context.handle(
        _userFeedbackMeta,
        userFeedback.isAcceptableOrUnknown(
          data['user_feedback']!,
          _userFeedbackMeta,
        ),
      );
    }
    return context;
  }

