class PlanAdjustment extends DataClass implements Insertable<PlanAdjustment> {
  final String id;

  /// Adjustment type
  final String type;

  /// Domain: workout, meal, recovery, both
  final String domain;

  /// Reason (English)
  final String reason;
  final String? reasonAr;

  /// Explanation
  final String? explanation;
  final String? explanationAr;

  /// Trigger
  final String trigger;
  final String? triggerAr;

  /// Values (JSON)
  final String originalValueJson;
  final String proposedValueJson;

  /// Affected day (0-6, null = whole week)
  final int? affectedDayIndex;

  /// Scores
  final int impactScore;
  final int confidence;

  /// Status
  final String status;

  /// Related plan IDs
  final String? mealPlanId;
  final String? workoutPlanId;
  final String? masterPlanId;

  /// Timestamps
  final DateTime createdAt;
  final DateTime? appliedAt;
  final DateTime? revertedAt;

  /// User feedback
  final String? userFeedback;
  const PlanAdjustment({
    required this.id,
    required this.type,
    required this.domain,
    required this.reason,
    this.reasonAr,
    this.explanation,
    this.explanationAr,
    required this.trigger,
    this.triggerAr,
    required this.originalValueJson,
    required this.proposedValueJson,
    this.affectedDayIndex,
    required this.impactScore,
    required this.confidence,
    required this.status,
    this.mealPlanId,
    this.workoutPlanId,
    this.masterPlanId,
    required this.createdAt,
    this.appliedAt,
    this.revertedAt,
    this.userFeedback,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['type'] = Variable<String>(type);
    map['domain'] = Variable<String>(domain);
    map['reason'] = Variable<String>(reason);
    if (!nullToAbsent || reasonAr != null) {
      map['reason_ar'] = Variable<String>(reasonAr);
    }
    if (!nullToAbsent || explanation != null) {
      map['explanation'] = Variable<String>(explanation);
    }
    if (!nullToAbsent || explanationAr != null) {
      map['explanation_ar'] = Variable<String>(explanationAr);
    }
    map['trigger'] = Variable<String>(trigger);
    if (!nullToAbsent || triggerAr != null) {
      map['trigger_ar'] = Variable<String>(triggerAr);
    }
    map['original_value_json'] = Variable<String>(originalValueJson);
    map['proposed_value_json'] = Variable<String>(proposedValueJson);
    if (!nullToAbsent || affectedDayIndex != null) {
      map['affected_day_index'] = Variable<int>(affectedDayIndex);
    }
    map['impact_score'] = Variable<int>(impactScore);
    map['confidence'] = Variable<int>(confidence);
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || mealPlanId != null) {
      map['meal_plan_id'] = Variable<String>(mealPlanId);
    }
    if (!nullToAbsent || workoutPlanId != null) {
      map['workout_plan_id'] = Variable<String>(workoutPlanId);
    }
    if (!nullToAbsent || masterPlanId != null) {
      map['master_plan_id'] = Variable<String>(masterPlanId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || appliedAt != null) {
      map['applied_at'] = Variable<DateTime>(appliedAt);
    }
    if (!nullToAbsent || revertedAt != null) {
      map['reverted_at'] = Variable<DateTime>(revertedAt);
    }
    if (!nullToAbsent || userFeedback != null) {
      map['user_feedback'] = Variable<String>(userFeedback);
    }
    return map;
  }

  PlanAdjustmentsCompanion toCompanion(bool nullToAbsent) {
    return PlanAdjustmentsCompanion(
      id: Value(id),
