    map['current_strain'] = Variable<double>(currentStrain);
    map['target_met'] = Variable<bool>(targetMet);
    map['suggested_intensity'] = Variable<String>(suggestedIntensity);
    map['recommendation'] = Variable<String>(recommendation);
    map['recommendation_ar'] = Variable<String>(recommendationAr);
    if (!nullToAbsent || guidance != null) {
      map['guidance'] = Variable<String>(guidance);
    }
    if (!nullToAbsent || guidanceAr != null) {
      map['guidance_ar'] = Variable<String>(guidanceAr);
    }
    return map;
  }

