          ..write('currentStrain: $currentStrain, ')
          ..write('targetMet: $targetMet, ')
          ..write('suggestedIntensity: $suggestedIntensity, ')
          ..write('recommendation: $recommendation, ')
          ..write('recommendationAr: $recommendationAr, ')
          ..write('guidance: $guidance, ')
          ..write('guidanceAr: $guidanceAr, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

