class SleepNeed extends DataClass implements Insertable<SleepNeed> {
  final String id;
  final DateTime date;
  final DateTime calculatedAt;

  /// Sleep need components (in hours)
  final double baseNeed;
  final double debtPayback;
  final double strainAdjustment;
  final double totalNeed;

  /// Input values
  final double sleepDebt;
  final double strainScore;

  /// Recommended times
  final DateTime? recommendedBedtime;
  final DateTime? recommendedWakeTime;

  /// User's typical wake time for calculations
  final int? wakeTimeHour;
  final int? wakeTimeMinute;

  /// Actual sleep achieved (filled next day)
  final double? actualSleep;

  /// Quality rating
  final String? qualityRating;
  const SleepNeed({
    required this.id,
    required this.date,
    required this.calculatedAt,
    required this.baseNeed,
    required this.debtPayback,
    required this.strainAdjustment,
    required this.totalNeed,
    required this.sleepDebt,
    required this.strainScore,
    this.recommendedBedtime,
    this.recommendedWakeTime,
    this.wakeTimeHour,
    this.wakeTimeMinute,
    this.actualSleep,
    this.qualityRating,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['date'] = Variable<DateTime>(date);
    map['calculated_at'] = Variable<DateTime>(calculatedAt);
    map['base_need'] = Variable<double>(baseNeed);
    map['debt_payback'] = Variable<double>(debtPayback);
    map['strain_adjustment'] = Variable<double>(strainAdjustment);
    map['total_need'] = Variable<double>(totalNeed);
    map['sleep_debt'] = Variable<double>(sleepDebt);
    map['strain_score'] = Variable<double>(strainScore);
    if (!nullToAbsent || recommendedBedtime != null) {
      map['recommended_bedtime'] = Variable<DateTime>(recommendedBedtime);
    }
    if (!nullToAbsent || recommendedWakeTime != null) {
      map['recommended_wake_time'] = Variable<DateTime>(recommendedWakeTime);
    }
    if (!nullToAbsent || wakeTimeHour != null) {
      map['wake_time_hour'] = Variable<int>(wakeTimeHour);
    }
    if (!nullToAbsent || wakeTimeMinute != null) {
      map['wake_time_minute'] = Variable<int>(wakeTimeMinute);
    }
    if (!nullToAbsent || actualSleep != null) {
      map['actual_sleep'] = Variable<double>(actualSleep);
    }
    if (!nullToAbsent || qualityRating != null) {
      map['quality_rating'] = Variable<String>(qualityRating);
    }
    return map;
  }

  SleepNeedsCompanion toCompanion(bool nullToAbsent) {
    return SleepNeedsCompanion(
      id: Value(id),
      date: Value(date),
      calculatedAt: Value(calculatedAt),
      baseNeed: Value(baseNeed),
      debtPayback: Value(debtPayback),
      strainAdjustment: Value(strainAdjustment),
      totalNeed: Value(totalNeed),
      sleepDebt: Value(sleepDebt),
      strainScore: Value(strainScore),
      recommendedBedtime: recommendedBedtime == null && nullToAbsent
          ? const Value.absent()
          : Value(recommendedBedtime),
      recommendedWakeTime: recommendedWakeTime == null && nullToAbsent
          ? const Value.absent()
          : Value(recommendedWakeTime),
      wakeTimeHour: wakeTimeHour == null && nullToAbsent
          ? const Value.absent()
          : Value(wakeTimeHour),
      wakeTimeMinute: wakeTimeMinute == null && nullToAbsent
          ? const Value.absent()
          : Value(wakeTimeMinute),
      actualSleep: actualSleep == null && nullToAbsent
          ? const Value.absent()
          : Value(actualSleep),
      qualityRating: qualityRating == null && nullToAbsent
          ? const Value.absent()
          : Value(qualityRating),
