class Streak extends DataClass implements Insertable<Streak> {
  final String id;

  /// Streak type: strainTarget, optimalSleep, highRecovery, mealLogging, etc.
  final String type;

  /// Current streak count
  final int currentCount;

  /// Longest ever achieved
  final int longestEver;

  /// When this streak started
  final DateTime? startedAt;

  /// Last day the streak was maintained
  final DateTime? lastAchievedAt;

  /// When the streak was broken (null if active)
  final DateTime? brokenAt;

  /// Whether the streak is currently active
  final bool isActive;

  /// Target value for the streak (e.g., 70 for 70% recovery)
  final int? targetValue;

  /// Timestamps
  final DateTime createdAt;
  final DateTime updatedAt;
  const Streak({
    required this.id,
    required this.type,
    required this.currentCount,
    required this.longestEver,
    this.startedAt,
    this.lastAchievedAt,
    this.brokenAt,
    required this.isActive,
    this.targetValue,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['type'] = Variable<String>(type);
    map['current_count'] = Variable<int>(currentCount);
    map['longest_ever'] = Variable<int>(longestEver);
    if (!nullToAbsent || startedAt != null) {
      map['started_at'] = Variable<DateTime>(startedAt);
    }
    if (!nullToAbsent || lastAchievedAt != null) {
      map['last_achieved_at'] = Variable<DateTime>(lastAchievedAt);
    }
    if (!nullToAbsent || brokenAt != null) {
      map['broken_at'] = Variable<DateTime>(brokenAt);
    }
    map['is_active'] = Variable<bool>(isActive);
    if (!nullToAbsent || targetValue != null) {
      map['target_value'] = Variable<int>(targetValue);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  StreaksCompanion toCompanion(bool nullToAbsent) {
    return StreaksCompanion(
      id: Value(id),
      type: Value(type),
      currentCount: Value(currentCount),
      longestEver: Value(longestEver),
      startedAt: startedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(startedAt),
      lastAchievedAt: lastAchievedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastAchievedAt),
      brokenAt: brokenAt == null && nullToAbsent
          ? const Value.absent()
          : Value(brokenAt),
      isActive: Value(isActive),
      targetValue: targetValue == null && nullToAbsent
          ? const Value.absent()
          : Value(targetValue),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Streak.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Streak(
      id: serializer.fromJson<String>(json['id']),
      type: serializer.fromJson<String>(json['type']),
      currentCount: serializer.fromJson<int>(json['currentCount']),
      longestEver: serializer.fromJson<int>(json['longestEver']),
      startedAt: serializer.fromJson<DateTime?>(json['startedAt']),
      lastAchievedAt: serializer.fromJson<DateTime?>(json['lastAchievedAt']),
      brokenAt: serializer.fromJson<DateTime?>(json['brokenAt']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      targetValue: serializer.fromJson<int?>(json['targetValue']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'type': serializer.toJson<String>(type),
      'currentCount': serializer.toJson<int>(currentCount),
      'longestEver': serializer.toJson<int>(longestEver),
      'startedAt': serializer.toJson<DateTime?>(startedAt),
      'lastAchievedAt': serializer.toJson<DateTime?>(lastAchievedAt),
      'brokenAt': serializer.toJson<DateTime?>(brokenAt),
      'isActive': serializer.toJson<bool>(isActive),
      'targetValue': serializer.toJson<int?>(targetValue),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Streak copyWith({
    String? id,
    String? type,
    int? currentCount,
    int? longestEver,
    Value<DateTime?> startedAt = const Value.absent(),
    Value<DateTime?> lastAchievedAt = const Value.absent(),
    Value<DateTime?> brokenAt = const Value.absent(),
