class PersonalRecord extends DataClass implements Insertable<PersonalRecord> {
  final String id;

  /// Category: recovery, strain, sleep, activity, nutrition, streaks, consistency
  final String category;

  /// Specific metric: highestRecovery, highestHrv, longestSleep, etc.
  final String metric;

  /// Record value
  final double value;

  /// Formatted value for display
  final String? formattedValue;

  /// When this record was achieved
  final DateTime achievedAt;

  /// Previous record value
  final double? previousValue;
  final DateTime? previousAchievedAt;

  /// Is this the all-time best?
  final bool isAllTime;

  /// Times this record has been broken
  final int timesImproved;

  /// Additional context (e.g., workout type)
  final String? context;
  const PersonalRecord({
    required this.id,
    required this.category,
    required this.metric,
    required this.value,
    this.formattedValue,
    required this.achievedAt,
    this.previousValue,
    this.previousAchievedAt,
    required this.isAllTime,
    required this.timesImproved,
    this.context,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['category'] = Variable<String>(category);
    map['metric'] = Variable<String>(metric);
    map['value'] = Variable<double>(value);
    if (!nullToAbsent || formattedValue != null) {
      map['formatted_value'] = Variable<String>(formattedValue);
    }
    map['achieved_at'] = Variable<DateTime>(achievedAt);
    if (!nullToAbsent || previousValue != null) {
      map['previous_value'] = Variable<double>(previousValue);
    }
    if (!nullToAbsent || previousAchievedAt != null) {
      map['previous_achieved_at'] = Variable<DateTime>(previousAchievedAt);
    }
    map['is_all_time'] = Variable<bool>(isAllTime);
    map['times_improved'] = Variable<int>(timesImproved);
    if (!nullToAbsent || context != null) {
      map['context'] = Variable<String>(context);
    }
    return map;
  }

  PersonalRecordsCompanion toCompanion(bool nullToAbsent) {
    return PersonalRecordsCompanion(
      id: Value(id),
      category: Value(category),
      metric: Value(metric),
      value: Value(value),
      formattedValue: formattedValue == null && nullToAbsent
          ? const Value.absent()
          : Value(formattedValue),
      achievedAt: Value(achievedAt),
      previousValue: previousValue == null && nullToAbsent
          ? const Value.absent()
          : Value(previousValue),
      previousAchievedAt: previousAchievedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(previousAchievedAt),
      isAllTime: Value(isAllTime),
      timesImproved: Value(timesImproved),
      context: context == null && nullToAbsent
          ? const Value.absent()
          : Value(context),
    );
  }

  factory PersonalRecord.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return PersonalRecord(
      id: serializer.fromJson<String>(json['id']),
      category: serializer.fromJson<String>(json['category']),
      metric: serializer.fromJson<String>(json['metric']),
      value: serializer.fromJson<double>(json['value']),
      formattedValue: serializer.fromJson<String?>(json['formattedValue']),
      achievedAt: serializer.fromJson<DateTime>(json['achievedAt']),
      previousValue: serializer.fromJson<double?>(json['previousValue']),
      previousAchievedAt: serializer.fromJson<DateTime?>(
        json['previousAchievedAt'],
      ),
      isAllTime: serializer.fromJson<bool>(json['isAllTime']),
      timesImproved: serializer.fromJson<int>(json['timesImproved']),
      context: serializer.fromJson<String?>(json['context']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'category': serializer.toJson<String>(category),
      'metric': serializer.toJson<String>(metric),
      'value': serializer.toJson<double>(value),
      'formattedValue': serializer.toJson<String?>(formattedValue),
      'achievedAt': serializer.toJson<DateTime>(achievedAt),
      'previousValue': serializer.toJson<double?>(previousValue),
      'previousAchievedAt': serializer.toJson<DateTime?>(previousAchievedAt),
      'isAllTime': serializer.toJson<bool>(isAllTime),
      'timesImproved': serializer.toJson<int>(timesImproved),
      'context': serializer.toJson<String?>(context),
    };
  }

  PersonalRecord copyWith({
    String? id,
    String? category,
    String? metric,
    double? value,
    Value<String?> formattedValue = const Value.absent(),
    DateTime? achievedAt,
    Value<double?> previousValue = const Value.absent(),
    Value<DateTime?> previousAchievedAt = const Value.absent(),
    bool? isAllTime,
    int? timesImproved,
    Value<String?> context = const Value.absent(),
  }) => PersonalRecord(
    id: id ?? this.id,
    category: category ?? this.category,
    metric: metric ?? this.metric,
    value: value ?? this.value,
    formattedValue: formattedValue.present
        ? formattedValue.value
        : this.formattedValue,
    achievedAt: achievedAt ?? this.achievedAt,
    previousValue: previousValue.present
        ? previousValue.value
        : this.previousValue,
    previousAchievedAt: previousAchievedAt.present
        ? previousAchievedAt.value
        : this.previousAchievedAt,
    isAllTime: isAllTime ?? this.isAllTime,
    timesImproved: timesImproved ?? this.timesImproved,
    context: context.present ? context.value : this.context,
  );
  PersonalRecord copyWithCompanion(PersonalRecordsCompanion data) {
    return PersonalRecord(
      id: data.id.present ? data.id.value : this.id,
      category: data.category.present ? data.category.value : this.category,
      metric: data.metric.present ? data.metric.value : this.metric,
      value: data.value.present ? data.value.value : this.value,
      formattedValue: data.formattedValue.present
          ? data.formattedValue.value
          : this.formattedValue,
      achievedAt: data.achievedAt.present
          ? data.achievedAt.value
          : this.achievedAt,
      previousValue: data.previousValue.present
          ? data.previousValue.value
          : this.previousValue,
      previousAchievedAt: data.previousAchievedAt.present
          ? data.previousAchievedAt.value
          : this.previousAchievedAt,
      isAllTime: data.isAllTime.present ? data.isAllTime.value : this.isAllTime,
      timesImproved: data.timesImproved.present
          ? data.timesImproved.value
          : this.timesImproved,
      context: data.context.present ? data.context.value : this.context,
    );
  }

  @override
  String toString() {
    return (StringBuffer('PersonalRecord(')
          ..write('id: $id, ')
          ..write('category: $category, ')
          ..write('metric: $metric, ')
          ..write('value: $value, ')
          ..write('formattedValue: $formattedValue, ')
          ..write('achievedAt: $achievedAt, ')
          ..write('previousValue: $previousValue, ')
          ..write('previousAchievedAt: $previousAchievedAt, ')
          ..write('isAllTime: $isAllTime, ')
          ..write('timesImproved: $timesImproved, ')
          ..write('context: $context')
          ..write(')'))
        .toString();
  }

