class MonthlyAssessment extends DataClass
    implements Insertable<MonthlyAssessment> {
  final String id;
  final DateTime monthStart;
  final DateTime generatedAt;

  /// Monthly averages (JSON serialized MonthlyAverages)
  final String averagesJson;

  /// Month-over-month comparison (JSON serialized MonthlyComparison)
  final String? comparisonJson;

  /// Trend analyses (JSON serialized TrendAnalysis)
  final String recoveryTrendJson;
  final String strainTrendJson;
  final String sleepTrendJson;

  /// Behavior correlations (JSON arrays)
  final String positiveCorrelationsJson;
  final String negativeCorrelationsJson;

  /// Weekly breakdowns (JSON array)
  final String weeklyBreakdownsJson;

  /// Key insights (JSON array)
  final String insightsJson;

  /// AI-generated summaries
  final String? aiSummary;
  final String? aiSummaryAr;

  /// Best/worst days
  final DateTime? bestDay;
  final int? bestDayRecovery;
  final DateTime? worstDay;
  final int? worstDayRecovery;

  /// Workout/rest breakdown
  final int workoutDays;
  final int restDays;

  /// Streak data (JSON serialized MonthlyStreakData)
  final String? streakDataJson;

  /// Metadata
  final bool isAiGenerated;
  final int dataCompleteness;
  const MonthlyAssessment({
    required this.id,
    required this.monthStart,
    required this.generatedAt,
    required this.averagesJson,
    this.comparisonJson,
    required this.recoveryTrendJson,
    required this.strainTrendJson,
    required this.sleepTrendJson,
    required this.positiveCorrelationsJson,
    required this.negativeCorrelationsJson,
    required this.weeklyBreakdownsJson,
    required this.insightsJson,
    this.aiSummary,
    this.aiSummaryAr,
    this.bestDay,
    this.bestDayRecovery,
    this.worstDay,
    this.worstDayRecovery,
    required this.workoutDays,
    required this.restDays,
    this.streakDataJson,
    required this.isAiGenerated,
    required this.dataCompleteness,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['month_start'] = Variable<DateTime>(monthStart);
    map['generated_at'] = Variable<DateTime>(generatedAt);
    map['averages_json'] = Variable<String>(averagesJson);
    if (!nullToAbsent || comparisonJson != null) {
      map['comparison_json'] = Variable<String>(comparisonJson);
    }
    map['recovery_trend_json'] = Variable<String>(recoveryTrendJson);
    map['strain_trend_json'] = Variable<String>(strainTrendJson);
    map['sleep_trend_json'] = Variable<String>(sleepTrendJson);
    map['positive_correlations_json'] = Variable<String>(
      positiveCorrelationsJson,
    );
    map['negative_correlations_json'] = Variable<String>(
      negativeCorrelationsJson,
    );
    map['weekly_breakdowns_json'] = Variable<String>(weeklyBreakdownsJson);
    map['insights_json'] = Variable<String>(insightsJson);
    if (!nullToAbsent || aiSummary != null) {
      map['ai_summary'] = Variable<String>(aiSummary);
    }
    if (!nullToAbsent || aiSummaryAr != null) {
      map['ai_summary_ar'] = Variable<String>(aiSummaryAr);
    }
    if (!nullToAbsent || bestDay != null) {
      map['best_day'] = Variable<DateTime>(bestDay);
    }
    if (!nullToAbsent || bestDayRecovery != null) {
      map['best_day_recovery'] = Variable<int>(bestDayRecovery);
    }
    if (!nullToAbsent || worstDay != null) {
      map['worst_day'] = Variable<DateTime>(worstDay);
    }
    if (!nullToAbsent || worstDayRecovery != null) {
      map['worst_day_recovery'] = Variable<int>(worstDayRecovery);
    }
    map['workout_days'] = Variable<int>(workoutDays);
    map['rest_days'] = Variable<int>(restDays);
    if (!nullToAbsent || streakDataJson != null) {
      map['streak_data_json'] = Variable<String>(streakDataJson);
    }
    map['is_ai_generated'] = Variable<bool>(isAiGenerated);
    map['data_completeness'] = Variable<int>(dataCompleteness);
    return map;
  }

  MonthlyAssessmentsCompanion toCompanion(bool nullToAbsent) {
    return MonthlyAssessmentsCompanion(
      id: Value(id),
      monthStart: Value(monthStart),
      generatedAt: Value(generatedAt),
      averagesJson: Value(averagesJson),
      comparisonJson: comparisonJson == null && nullToAbsent
          ? const Value.absent()
          : Value(comparisonJson),
      recoveryTrendJson: Value(recoveryTrendJson),
      strainTrendJson: Value(strainTrendJson),
      sleepTrendJson: Value(sleepTrendJson),
