          ..write('insightsJson: $insightsJson, ')
          ..write('aiSummary: $aiSummary, ')
          ..write('aiSummaryAr: $aiSummaryAr, ')
          ..write('bestDay: $bestDay, ')
          ..write('bestDayRecovery: $bestDayRecovery, ')
          ..write('worstDay: $worstDay, ')
          ..write('worstDayRecovery: $worstDayRecovery, ')
          ..write('workoutDays: $workoutDays, ')
          ..write('restDays: $restDays, ')
          ..write('streakDataJson: $streakDataJson, ')
          ..write('isAiGenerated: $isAiGenerated, ')
          ..write('dataCompleteness: $dataCompleteness, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

