class HealthspanRecord extends DataClass
    implements Insertable<HealthspanRecord> {
  final String id;
  final DateTime calculatedAt;

  /// Ages
  final int chronologicalAge;
  final int biologicalAge;
  final int ageDifference;

  /// Individual factor adjustments
  final int hrvAdjustment;
  final int rhrAdjustment;
  final int sleepAdjustment;
  final int activityAdjustment;
  final int recoveryAdjustment;

  /// Input metrics used
  final int? avgHrv;
  final int? avgRhr;
  final double? avgSleepHours;
  final int? avgSleepQuality;
  final int? weeklyActiveMinutes;
  final int? avgRecovery;
  final int? weeklyWorkouts;

  /// Reference baselines (JSON serialized)
  final String? hrvBaselinesJson;
  final String? rhrBaselinesJson;

  /// All factor details (JSON serialized List<HealthspanFactor>)
  final String factorsJson;

  /// Recommendations (JSON array)
  final String recommendationsJson;

  /// Confidence score
  final int confidence;
  const HealthspanRecord({
    required this.id,
    required this.calculatedAt,
    required this.chronologicalAge,
    required this.biologicalAge,
    required this.ageDifference,
    required this.hrvAdjustment,
    required this.rhrAdjustment,
    required this.sleepAdjustment,
    required this.activityAdjustment,
    required this.recoveryAdjustment,
    this.avgHrv,
    this.avgRhr,
    this.avgSleepHours,
    this.avgSleepQuality,
    this.weeklyActiveMinutes,
    this.avgRecovery,
    this.weeklyWorkouts,
    this.hrvBaselinesJson,
    this.rhrBaselinesJson,
    required this.factorsJson,
    required this.recommendationsJson,
    required this.confidence,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['calculated_at'] = Variable<DateTime>(calculatedAt);
    map['chronological_age'] = Variable<int>(chronologicalAge);
    map['biological_age'] = Variable<int>(biologicalAge);
    map['age_difference'] = Variable<int>(ageDifference);
    map['hrv_adjustment'] = Variable<int>(hrvAdjustment);
    map['rhr_adjustment'] = Variable<int>(rhrAdjustment);
    map['sleep_adjustment'] = Variable<int>(sleepAdjustment);
    map['activity_adjustment'] = Variable<int>(activityAdjustment);
    map['recovery_adjustment'] = Variable<int>(recoveryAdjustment);
    if (!nullToAbsent || avgHrv != null) {
      map['avg_hrv'] = Variable<int>(avgHrv);
    }
    if (!nullToAbsent || avgRhr != null) {
      map['avg_rhr'] = Variable<int>(avgRhr);
    }
    if (!nullToAbsent || avgSleepHours != null) {
      map['avg_sleep_hours'] = Variable<double>(avgSleepHours);
    }
    if (!nullToAbsent || avgSleepQuality != null) {
      map['avg_sleep_quality'] = Variable<int>(avgSleepQuality);
    }
    if (!nullToAbsent || weeklyActiveMinutes != null) {
      map['weekly_active_minutes'] = Variable<int>(weeklyActiveMinutes);
    }
    if (!nullToAbsent || avgRecovery != null) {
      map['avg_recovery'] = Variable<int>(avgRecovery);
    }
    if (!nullToAbsent || weeklyWorkouts != null) {
      map['weekly_workouts'] = Variable<int>(weeklyWorkouts);
    }
    if (!nullToAbsent || hrvBaselinesJson != null) {
      map['hrv_baselines_json'] = Variable<String>(hrvBaselinesJson);
    }
    if (!nullToAbsent || rhrBaselinesJson != null) {
      map['rhr_baselines_json'] = Variable<String>(rhrBaselinesJson);
    }
    map['factors_json'] = Variable<String>(factorsJson);
    map['recommendations_json'] = Variable<String>(recommendationsJson);
    map['confidence'] = Variable<int>(confidence);
    return map;
  }

  HealthspanRecordsCompanion toCompanion(bool nullToAbsent) {
    return HealthspanRecordsCompanion(
      id: Value(id),
      calculatedAt: Value(calculatedAt),
      chronologicalAge: Value(chronologicalAge),
      biologicalAge: Value(biologicalAge),
      ageDifference: Value(ageDifference),
      hrvAdjustment: Value(hrvAdjustment),
      rhrAdjustment: Value(rhrAdjustment),
      sleepAdjustment: Value(sleepAdjustment),
      activityAdjustment: Value(activityAdjustment),
      recoveryAdjustment: Value(recoveryAdjustment),
      avgHrv: avgHrv == null && nullToAbsent
          ? const Value.absent()
          : Value(avgHrv),
      avgRhr: avgRhr == null && nullToAbsent
          ? const Value.absent()
          : Value(avgRhr),
      avgSleepHours: avgSleepHours == null && nullToAbsent
          ? const Value.absent()
          : Value(avgSleepHours),
      avgSleepQuality: avgSleepQuality == null && nullToAbsent
          ? const Value.absent()
          : Value(avgSleepQuality),
      weeklyActiveMinutes: weeklyActiveMinutes == null && nullToAbsent
          ? const Value.absent()
          : Value(weeklyActiveMinutes),
      avgRecovery: avgRecovery == null && nullToAbsent
          ? const Value.absent()
          : Value(avgRecovery),
      weeklyWorkouts: weeklyWorkouts == null && nullToAbsent
          ? const Value.absent()
          : Value(weeklyWorkouts),
      hrvBaselinesJson: hrvBaselinesJson == null && nullToAbsent
          ? const Value.absent()
          : Value(hrvBaselinesJson),
      rhrBaselinesJson: rhrBaselinesJson == null && nullToAbsent
          ? const Value.absent()
          : Value(rhrBaselinesJson),
      factorsJson: Value(factorsJson),
      recommendationsJson: Value(recommendationsJson),
      confidence: Value(confidence),
    );
  }

  factory HealthspanRecord.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return HealthspanRecord(
      id: serializer.fromJson<String>(json['id']),
      calculatedAt: serializer.fromJson<DateTime>(json['calculatedAt']),
      chronologicalAge: serializer.fromJson<int>(json['chronologicalAge']),
      biologicalAge: serializer.fromJson<int>(json['biologicalAge']),
      ageDifference: serializer.fromJson<int>(json['ageDifference']),
      hrvAdjustment: serializer.fromJson<int>(json['hrvAdjustment']),
      rhrAdjustment: serializer.fromJson<int>(json['rhrAdjustment']),
      sleepAdjustment: serializer.fromJson<int>(json['sleepAdjustment']),
      activityAdjustment: serializer.fromJson<int>(json['activityAdjustment']),
      recoveryAdjustment: serializer.fromJson<int>(json['recoveryAdjustment']),
      avgHrv: serializer.fromJson<int?>(json['avgHrv']),
      avgRhr: serializer.fromJson<int?>(json['avgRhr']),
      avgSleepHours: serializer.fromJson<double?>(json['avgSleepHours']),
      avgSleepQuality: serializer.fromJson<int?>(json['avgSleepQuality']),
      weeklyActiveMinutes: serializer.fromJson<int?>(
        json['weeklyActiveMinutes'],
      ),
