    map['recovery_score'] = Variable<int>(recoveryScore);
    map['recovery_state'] = Variable<String>(recoveryState);
    map['strain_target_json'] = Variable<String>(strainTargetJson);
    map['sleep_outlook_json'] = Variable<String>(sleepOutlookJson);
    map['recommended_activities_json'] = Variable<String>(
      recommendedActivitiesJson,
    );
    map['behaviors_to_track_json'] = Variable<String>(behaviorsToTrackJson);
    map['insights_json'] = Variable<String>(insightsJson);
    map['top_actions_json'] = Variable<String>(topActionsJson);
    map['top_actions_ar_json'] = Variable<String>(topActionsArJson);
    map['warnings_json'] = Variable<String>(warningsJson);
    map['warnings_ar_json'] = Variable<String>(warningsArJson);
    if (!nullToAbsent || coachingMessage != null) {
      map['coaching_message'] = Variable<String>(coachingMessage);
    }
    if (!nullToAbsent || coachingMessageAr != null) {
      map['coaching_message_ar'] = Variable<String>(coachingMessageAr);
    }
    map['is_ai_generated'] = Variable<bool>(isAiGenerated);
    map['confidence'] = Variable<int>(confidence);
    return map;
  }

