      aiSummary: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}ai_summary'],
      ),
      aiSummaryAr: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}ai_summary_ar'],
      ),
      overallScore: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}overall_score'],
      )!,
      isAiGenerated: attachedDatabase.typeMapping.read(
        DriftSqlType.bool,
        data['${effectivePrefix}is_ai_generated'],
      )!,
      confidence: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}confidence'],
      )!,
    );
  }

  @override
  $DayReviewsTable createAlias(String alias) {
    return $DayReviewsTable(attachedDatabase, alias);
  }
}

class DayReview extends DataClass implements Insertable<DayReview> {
  final String id;
  final DateTime date;
  final DateTime generatedAt;

  /// Strain review (JSON serialized StrainReview)
  final String strainReviewJson;

  /// Sleep review (JSON serialized SleepReview)
  final String sleepReviewJson;

  /// Nutrition review (JSON serialized NutritionReview)
  final String? nutritionReviewJson;

  /// Recovery prediction (JSON serialized RecoveryPrediction)
  final String recoveryPredictionJson;

  /// Behavior impacts (JSON array)
  final String behaviorImpactsJson;

  /// What went well
  final String whatWentWellJson;
  final String whatWentWellArJson;

  /// Areas to improve
  final String areasToImproveJson;
  final String areasToImproveArJson;

  /// Sleep recommendation
  final double sleepRecommendationHours;
  final DateTime? recommendedBedtime;

  /// AI-generated summary
  final String? aiSummary;
  final String? aiSummaryAr;

  /// Overall day score (0-100)
  final int overallScore;

  /// Metadata
  final bool isAiGenerated;
  final int confidence;
