    required this.whatWentWellJson,
    required this.whatWentWellArJson,
    required this.areasToImproveJson,
    required this.areasToImproveArJson,
    required this.sleepRecommendationHours,
    this.recommendedBedtime,
    this.aiSummary,
    this.aiSummaryAr,
    required this.overallScore,
    required this.isAiGenerated,
    required this.confidence,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['date'] = Variable<DateTime>(date);
    map['generated_at'] = Variable<DateTime>(generatedAt);
    map['strain_review_json'] = Variable<String>(strainReviewJson);
    map['sleep_review_json'] = Variable<String>(sleepReviewJson);
    if (!nullToAbsent || nutritionReviewJson != null) {
      map['nutrition_review_json'] = Variable<String>(nutritionReviewJson);
    }
    map['recovery_prediction_json'] = Variable<String>(recoveryPredictionJson);
    map['behavior_impacts_json'] = Variable<String>(behaviorImpactsJson);
    map['what_went_well_json'] = Variable<String>(whatWentWellJson);
    map['what_went_well_ar_json'] = Variable<String>(whatWentWellArJson);
    map['areas_to_improve_json'] = Variable<String>(areasToImproveJson);
    map['areas_to_improve_ar_json'] = Variable<String>(areasToImproveArJson);
    map['sleep_recommendation_hours'] = Variable<double>(
      sleepRecommendationHours,
    );
    if (!nullToAbsent || recommendedBedtime != null) {
      map['recommended_bedtime'] = Variable<DateTime>(recommendedBedtime);
    }
    if (!nullToAbsent || aiSummary != null) {
      map['ai_summary'] = Variable<String>(aiSummary);
    }
    if (!nullToAbsent || aiSummaryAr != null) {
      map['ai_summary_ar'] = Variable<String>(aiSummaryAr);
    }
    map['overall_score'] = Variable<int>(overallScore);
    map['is_ai_generated'] = Variable<bool>(isAiGenerated);
    map['confidence'] = Variable<int>(confidence);
    return map;
  }

