    if (overallScore.present) {
      map['overall_score'] = Variable<int>(overallScore.value);
    }
    if (isAiGenerated.present) {
      map['is_ai_generated'] = Variable<bool>(isAiGenerated.value);
    }
    if (confidence.present) {
      map['confidence'] = Variable<int>(confidence.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('DayReviewsCompanion(')
          ..write('id: $id, ')
          ..write('date: $date, ')
          ..write('generatedAt: $generatedAt, ')
          ..write('strainReviewJson: $strainReviewJson, ')
          ..write('sleepReviewJson: $sleepReviewJson, ')
          ..write('nutritionReviewJson: $nutritionReviewJson, ')
          ..write('recoveryPredictionJson: $recoveryPredictionJson, ')
          ..write('behaviorImpactsJson: $behaviorImpactsJson, ')
          ..write('whatWentWellJson: $whatWentWellJson, ')
          ..write('whatWentWellArJson: $whatWentWellArJson, ')
          ..write('areasToImproveJson: $areasToImproveJson, ')
          ..write('areasToImproveArJson: $areasToImproveArJson, ')
          ..write('sleepRecommendationHours: $sleepRecommendationHours, ')
          ..write('recommendedBedtime: $recommendedBedtime, ')
          ..write('aiSummary: $aiSummary, ')
          ..write('aiSummaryAr: $aiSummaryAr, ')
          ..write('overallScore: $overallScore, ')
          ..write('isAiGenerated: $isAiGenerated, ')
          ..write('confidence: $confidence, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

