class AllTimeStat extends DataClass implements Insertable<AllTimeStat> {
  final String id;
  final String userId;
  final DateTime calculatedAt;

  /// Total counts
  final int totalDaysTracked;
  final int totalWorkouts;
  final int totalMealsLogged;
  final int totalCaloriesBurned;
  final int totalSteps;
  final double totalSleepHours;

  /// Averages
  final double avgRecovery;
  final double avgStrain;

  /// Best periods
  final DateTime? bestWeekDate;
  final double? bestWeekScore;
  final DateTime? bestMonthDate;
  final double? bestMonthScore;

  /// Personal records reference
  final String recordsJson;

  /// Last updated
  final DateTime updatedAt;
  const AllTimeStat({
    required this.id,
    required this.userId,
    required this.calculatedAt,
    required this.totalDaysTracked,
    required this.totalWorkouts,
    required this.totalMealsLogged,
    required this.totalCaloriesBurned,
    required this.totalSteps,
    required this.totalSleepHours,
    required this.avgRecovery,
    required this.avgStrain,
    this.bestWeekDate,
    this.bestWeekScore,
    this.bestMonthDate,
    this.bestMonthScore,
    required this.recordsJson,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['user_id'] = Variable<String>(userId);
    map['calculated_at'] = Variable<DateTime>(calculatedAt);
    map['total_days_tracked'] = Variable<int>(totalDaysTracked);
    map['total_workouts'] = Variable<int>(totalWorkouts);
    map['total_meals_logged'] = Variable<int>(totalMealsLogged);
    map['total_calories_burned'] = Variable<int>(totalCaloriesBurned);
    map['total_steps'] = Variable<int>(totalSteps);
    map['total_sleep_hours'] = Variable<double>(totalSleepHours);
    map['avg_recovery'] = Variable<double>(avgRecovery);
    map['avg_strain'] = Variable<double>(avgStrain);
    if (!nullToAbsent || bestWeekDate != null) {
      map['best_week_date'] = Variable<DateTime>(bestWeekDate);
    }
    if (!nullToAbsent || bestWeekScore != null) {
      map['best_week_score'] = Variable<double>(bestWeekScore);
    }
    if (!nullToAbsent || bestMonthDate != null) {
      map['best_month_date'] = Variable<DateTime>(bestMonthDate);
    }
    if (!nullToAbsent || bestMonthScore != null) {
      map['best_month_score'] = Variable<double>(bestMonthScore);
    }
    map['records_json'] = Variable<String>(recordsJson);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  AllTimeStatsCompanion toCompanion(bool nullToAbsent) {
    return AllTimeStatsCompanion(
      id: Value(id),
