  final DateTime consumedAt;

  /// Meal type: breakfast, lunch, dinner, snack, pre-workout, post-workout
  final String mealType;

  /// Meal name/description
  final String name;
  final double calories;
  final double protein;
  final double carbs;
  final double fats;
  final double? fiber;
  final double? sugar;
  final double? sodium;

  /// Ingredients (JSON array)
  final String? ingredientsJson;

  /// Notes
  final String? notes;

  /// Source: manual, apple-health, ai-logged, meal-template
  final String? source;

  /// Whether user can edit this meal
  final bool isEditable;

  /// Photo URI if available
  final String? photoUri;

  /// Link to original MealLog if migrated
  final String? mealLogId;

  /// Timestamps
  final DateTime createdAt;
  const MealsDetailedData({
    required this.id,
    required this.consumedAt,
    required this.mealType,
    required this.name,
    required this.calories,
    required this.protein,
    required this.carbs,
    required this.fats,
